def solve(s: str):
    """Run-length encode string s into list of [char, count]."""
    if not s:
        return []
    res = []
    prev = s[0]
    count = 1
    for ch in s[1:]:
        if ch == prev:
            count += 1
        else:
            res.append([prev, count])
            prev = ch
            count = 1
    res.append([prev, count])
