def solve(tokens):
    stack = []
    for t in tokens:
        # Skip empty strings or whitespace tokens
        if isinstance(t, str) and t.strip() == '':
            continue
        if t in '+-*/':
            # Assume enough operands per spec
            b = stack.pop()
            a = stack.pop()
            if t == '+':
                stack.append(a + b)
            elif t == '-':
                stack.append(a - b)
            elif t == '*':
                stack.append(a * b)
            else:
                # division truncates toward zero
                stack.append(int(a / b))
        else:
            stack.append(int(t))
    return stack[-1] if stack else 0

